package hu.synostream.android;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.*;
public class RecommendationsTest {
 JSONObject row(long id)throws Exception{return new JSONObject().put("id",id).put("title","Movie "+id).put("name","TV "+id).put("overview","Description").put("poster_path","/poster.jpg");}
 JSONObject results(int start,int count)throws Exception{JSONArray a=new JSONArray();for(int n=start;n<start+count;n++)a.put(row(n));return new JSONObject().put("results",a);}
 Library.Card seed(long id){Library.Card c=new Library.Card("/Movie.mkv","Seed "+id,true);c.id=id;return c;}
 Recommendations store(){return new Recommendations("{}",s->{},()->1000L,new Random(42));}
 void populate(Recommendations r,int start,int count)throws Exception{r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),(e,p)->results(start,count),()->false,()->{});}
 @Test public void normalizationRejectsAdultInvalidAndUnsafePoster()throws Exception{assertNull(Recommendations.normalize(row(1).put("adult",true),true,""));assertNull(Recommendations.normalize(row(0),true,""));assertNull(Recommendations.normalize(row(1).put("title","").put("original_title",""),true,""));assertEquals("",Recommendations.normalize(row(1).put("poster_path","https://evil/test"),true,"").optString("poster"));assertEquals("TV 1",Recommendations.normalize(row(1),false,"").optString("title"));}
 @Test public void excludesOwnedAcrossLibrariesAndKeepsTypeIdentity()throws Exception{Recommendations r=store();populate(r,1,5);List<JSONObject> items=r.draw("hu-HU",Set.of("movie/1","movie/2","tv/3"),Set.of(),false,12);assertEquals(3,items.size());assertTrue(items.stream().anyMatch(i->i.optLong("id")==3));}
 @Test public void feedbackPersistsAndHiddenTitlesAreNotRecommended()throws Exception{AtomicReference<String> saved=new AtomicReference<>();Recommendations r=new Recommendations("{}",saved::set,()->1000L,new Random(1));populate(r,10,4);JSONObject item=r.draw("hu-HU",Set.of(),Set.of(),false,1).get(0);r.feedback(item,"interested");Recommendations restored=new Recommendations(saved.get(),s->{},()->1000L,new Random(2));assertEquals(1,restored.feedback("interested",Set.of()).size());assertTrue(restored.draw("hu-HU",Set.of(),Set.of(),false,12).stream().noneMatch(i->i.optLong("id")==item.optLong("id")));restored.feedback(item,"dismissed");assertEquals(1,restored.feedback("dismissed",Set.of()).size());restored.feedback(item,"neutral");assertFalse(restored.responded(item));}
 @Test public void rotatesWithoutImmediateRepeatsWhenPoolIsLarge()throws Exception{Recommendations r=store();populate(r,10,30);List<JSONObject> first=r.draw("hu-HU",Set.of(),Set.of(),false,12);Set<String> previous=new HashSet<>();first.forEach(i->previous.add(Recommendations.key(i)));List<JSONObject> second=r.draw("hu-HU",Set.of(),previous,false,12);assertEquals(12,second.size());assertTrue(second.stream().noneMatch(i->previous.contains(Recommendations.key(i))));}
 @Test public void smallPoolStillWorks()throws Exception{Recommendations r=store();populate(r,10,2);r.draw("hu-HU",Set.of(),Set.of(),false,12);assertEquals(2,r.draw("hu-HU",Set.of(),Set.of("movie/10","movie/11"),false,12).size());}
 @Test public void capsNetworkRequestsAndReusesFreshCache()throws Exception{Recommendations r=store();List<Library.Card> seeds=new ArrayList<>();for(int n=1;n<11;n++)seeds.add(seed(n));AtomicInteger calls=new AtomicInteger(),active=new AtomicInteger(),peak=new AtomicInteger();Recognition.Api api=(e,p)->{calls.incrementAndGet();int a=active.incrementAndGet();peak.accumulateAndGet(a,Math::max);Thread.sleep(10);active.decrementAndGet();return results(20,2);};r.load(seeds,true,"hu-HU",false,Set.of(),api,()->false,()->{});assertEquals(4,calls.get());assertTrue(peak.get()<=4);List<Library.Card> one=List.of(seed(50));r.load(one,true,"hu-HU",false,Set.of(),api,()->false,()->{});int before=calls.get();r.load(one,true,"hu-HU",false,Set.of(),api,()->false,()->{});assertEquals(before,calls.get());}
 @Test public void expiredCacheRefreshesAndLanguagesAreSeparate()throws Exception{AtomicLong now=new AtomicLong(1000);Recommendations r=new Recommendations("{}",s->{},now::get,new Random());AtomicInteger calls=new AtomicInteger();Recognition.Api api=(e,p)->{calls.incrementAndGet();return results(20,2);};r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),api,()->false,()->{});now.addAndGet(Recommendations.TTL+1);r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),api,()->false,()->{});r.load(List.of(seed(1)),true,"en-US",false,Set.of(),api,()->false,()->{});assertEquals(3,calls.get());assertEquals(2,r.pool("en-US").size());}
 @Test public void partialFailurePreservesSuccessfulResults()throws Exception{Recommendations r=store();Recommendations.Outcome out=r.load(List.of(seed(1),seed(2)),true,"hu-HU",false,Set.of(),(e,p)->{if(e.startsWith("movie/1/"))throw new java.io.IOException();return results(20,2);},()->false,()->{});assertEquals(1,out.errors);assertEquals(2,r.pool("hu-HU").size());}
 @Test public void emptyResultIsCachedAndCancellationDoesNotRequest()throws Exception{Recommendations r=store();AtomicInteger calls=new AtomicInteger();Recognition.Api api=(e,p)->{calls.incrementAndGet();return results(1,0);};r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),api,()->false,()->{});r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),api,()->false,()->{});assertEquals(1,calls.get());assertThrows(InterruptedException.class,()->r.load(List.of(seed(2)),true,"hu-HU",false,Set.of(),api,()->true,()->{}));assertEquals(1,calls.get());}
 @Test public void removedSeedsDoNotKeepContributing()throws Exception{Recommendations r=store();populate(r,10,3);r.load(List.of(),true,"hu-HU",false,Set.of(),(e,p)->{throw new AssertionError();},()->false,()->{});assertTrue(r.pool("hu-HU").isEmpty());}
 @Test public void hungarianPreferenceRequiresTranslationsAndSkipsOwned()throws Exception{Recommendations r=store();AtomicInteger translations=new AtomicInteger();r.load(List.of(seed(1)),true,"hu-HU",true,Set.of("movie/10"),(e,p)->{if(e.endsWith("/recommendations"))return results(10,3);translations.incrementAndGet();assertFalse(e.startsWith("movie/10/"));JSONObject data=new JSONObject().put("overview","Magyar leírás").put("title","Magyar cím");return new JSONObject().put("translations",new JSONArray().put(new JSONObject().put("iso_639_1","hu").put("data",data)));},()->false,()->{});assertEquals(2,translations.get());List<JSONObject> batch=r.draw("hu-HU",Set.of("movie/10"),Set.of(),true,12);assertTrue(batch.stream().allMatch(i->i.optBoolean("has_hu")));assertEquals("Magyar cím",batch.get(0).optString("title"));}
 @Test public void interestedFeedbackAlsoSuppliesSeeds()throws Exception{Recommendations r=store();JSONObject item=Recommendations.normalize(row(77),true,"Seed");r.feedback(item,"interested");AtomicBoolean matched=new AtomicBoolean();r.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),(e,p)->{if(e.equals("movie/77/recommendations"))matched.set(true);return results(100,2);},()->false,()->{});assertTrue(matched.get());}

 @Test public void drawingLocalizedCopiesDoesNotMutateCachedMetadata()throws Exception{Recommendations r=store();populate(r,10,1);JSONObject cached=r.pool("hu-HU").get("movie/10");String original=cached.toString();Recommendations.put(r.object("hu"),"movie/10",new JSONObject().put("ok",true).put("title","Magyar cím").put("overview","Magyar leírás"));JSONObject display=r.draw("hu-HU",Set.of(),Set.of(),true,12).get(0);assertEquals("Magyar cím",display.optString("title"));assertEquals(original,cached.toString());assertFalse(cached.has("has_hu"));JSONObject plain=r.draw("hu-HU",Set.of(),Set.of(),false,12).get(0);assertEquals("Movie 10",plain.optString("title"));assertEquals("Description",plain.optString("overview"));r.feedback(display,"interested");assertEquals("Magyar cím",r.feedback("interested",Set.of()).get(0).optString("title"));assertEquals(original,cached.toString());}

 @Test public void newDescriptionsAreCappedAtWordBoundaryWithoutEllipsis()throws Exception{String longText="word ".repeat(200);String shortText="A short description.";String cut=Recommendations.normalize(row(1).put("overview",longText),true,"").optString("overview");assertTrue(cut.length()<=600);assertTrue(cut.endsWith("word"));assertFalse(cut.endsWith("…"));assertEquals(shortText,Recommendations.normalize(row(1).put("overview",shortText),true,"").optString("overview"));}
 @Test public void oldLongStateRemainsReadable()throws Exception{Recommendations original=store();populate(original,10,1);Recommendations.put(original.pool("hu-HU").get("movie/10"),"overview","legacy ".repeat(500));Recommendations restored=new Recommendations(original.state.toString(),s->{},()->1000L,new Random());assertEquals(1,restored.pool("hu-HU").size());assertEquals("Movie 10",restored.draw("hu-HU",Set.of(),Set.of(),false,12).get(0).optString("title"));}

 @Test public void legacyPresentationPollutionIsRefetchedWithoutLosingFeedback()throws Exception{Recommendations r=store();populate(r,10,1);JSONObject item=r.pool("hu-HU").get("movie/10");r.feedback(Recommendations.copy(item),"interested");Recommendations.put(item,"has_hu",true);Recommendations.put(item,"title","Previously overwritten");Recommendations restored=new Recommendations(r.state.toString(),v->{},()->1000L,new Random());assertTrue(restored.pool("hu-HU").isEmpty());assertEquals(1,restored.feedback("interested",Set.of()).size());AtomicInteger calls=new AtomicInteger();restored.load(List.of(seed(1)),true,"hu-HU",false,Set.of(),(e,p)->{calls.incrementAndGet();return results(20,1);},()->false,()->{});assertTrue(calls.get()>0);assertFalse(restored.pool("hu-HU").isEmpty());}
 @Test public void expiredHungarianMetadataCannotOverwriteNewerResult()throws Exception{Recommendations r=store();populate(r,10,1);Recommendations.put(r.object("hu"),"movie/10",new JSONObject().put("ok",true).put("time",1000L-Recommendations.TTL-1).put("title","Old translated title").put("overview","Old description"));JSONObject display=r.draw("hu-HU",Set.of(),Set.of(),true,12).get(0);assertEquals("Movie 10",display.optString("title"));assertFalse(display.optBoolean("has_hu"));}
 @Test public void translatedDescriptionsAreBoundedToo()throws Exception{Recommendations r=store();r.load(List.of(seed(1)),true,"hu-HU",true,Set.of(),(e,p)->e.endsWith("/recommendations")?results(10,1):new JSONObject().put("translations",new JSONArray().put(new JSONObject().put("iso_639_1","hu").put("data",new JSONObject().put("title","Magyar").put("overview","word ".repeat(1000))))),()->false,()->{});assertTrue(r.object("hu").getJSONObject("movie/10").getString("overview").length()<=600);}
}
